mapper.select:
SELECT ri.id, ri.return_no, ri.return_batch_no, (SELECT COUNT(*) FROM wms_return_qc_item qi WHERE qi.return_order_id = ri.id) AS sku_kinds, ri.erp_order_id, ri.platform_order_id, ri.platform, ri.sku_code, ri.warehouse_id, w.warehouse_name, ri.return_date, ri.return_reason, ri.total_quantity, ri.qualified_quantity, ri.unqualified_quantity, ri.to_damaged_quantity, ri.scrap_quantity, ri.return_status, ri.remark, ri.create_by, u.nickname AS create_by_name, ri.create_time ,DATE_FORMAT(ri.disposition_time, '%Y-%m-%d %H:%i:%s') AS disposition_time ,DATE_FORMAT(ri.processed_time, '%Y-%m-%d %H:%i:%s') AS processed_time FROM wms_return_inbound_order ri LEFT JOIN wms_warehouse w ON ri.warehouse_id = w.id LEFT JOIN sys_user u ON ri.create_by = u.user_id
ri.deleted = 0
AND ri.return_no LIKE CONCAT('%', #{qo.returnNo}, '%')
AND ri.platform_order_id LIKE CONCAT('%', #{qo.platformOrderId}, '%')
AND ri.platform = #{qo.platform}
AND EXISTS (SELECT 1 FROM wms_return_qc_item qsku WHERE qsku.return_order_id = ri.id AND qsku.sku_code = #{qo.skuCode})
AND ri.warehouse_id = #{qo.warehouseId}
AND ri.return_status = #{qo.returnStatus}
AND ri.return_date >= #{qo.returnDateStart}
AND ri.return_date <= #{qo.returnDateEnd}
ORDER BY ri.create_time DESC

SELECT ri.id, ri.return_no, ri.erp_order_id, ri.platform_order_id, ri.warehouse_id, w.warehouse_name, ri.return_date, ri.return_reason, ri.total_quantity, ri.qualified_quantity, ri.unqualified_quantity, ri.remark, ri.create_by, u.nickname AS create_by_name, ri.create_time FROM wms_return_inbound_order ri LEFT JOIN wms_warehouse w ON ri.warehouse_id = w.id LEFT JOIN sys_user u ON ri.create_by = u.user_id
ri.deleted = 0
AND ri.return_no LIKE CONCAT('%', #{qo.returnNo}, '%')
AND ri.platform_order_id LIKE CONCAT('%', #{qo.platformOrderId}, '%')
AND ri.warehouse_id = #{qo.warehouseId}
AND ri.return_date >= #{qo.returnDateStart}
AND ri.return_date <= #{qo.returnDateEnd}
ORDER BY ri.create_time DESC
